Exercice 3 : Analyse et interprétation du code JavaScript
Le fichier script.js contient une fonction pour confirmer la modification du statut d'une intervention. Un
extrait est donné ci-dessous (Fig.4).
Fig.4 : Extrait du code du fichier "script.js"
1 function confirmerModification(codeIntervention) {
2 let nouveauStatut = document.querySelector('input[name="statut_'+codeIntervention+'"]:checked');
3 let commentaire = document.getElementById("com_"+codeIntervention).value;
4
5 if (nouveauStatut == null) {
6 alert("Veuillez sélectionner un nouveau statut pour l'intervention " + codeIntervention);
7 return false;
8 }
9
10 if (commentaire.trim() == "") {
11 let confirmer = confirm("Aucun commentaire saisi. Voulez-vous continuer ?");
12 if (!confirmer) {
13 return false;
14 }
15 }
16
17 return true;
18 }
