Exercice 4 : Analyse et interprétation du code PHP
Le fichier afficher_interventions.php reçoit le matricule du technicien, interroge la base de données et affiche les
interventions correspondantes. Un extrait incomplet du code PHP est présenté ci-dessous (Fig.5).
Fig.5 : Extrait du code du fichier "afficher_interventions.php"
1 <?php
2 $matricule = $_POST["matricule"];
3
4 // Tâche ❶ : Connexion à la base de données
5 $con = mysqli_connect("localhost", "root", "", "gestion_parc") or die ("Erreur de connexion");
6
7 // Tâche ❷ : Requête pour récupérer les interventions du technicien
8 $req = "SELECT I.codeIntervention, I.dateIntervention, O.modeleOrd, P.libellePanne, I.statut
9 FROM Intervention I, Ordinateur O, TypePanne P
10 WHERE I.codeOrdinateur = O.codeOrdinateur
11 AND I.codeTypePanne = P.codeTypePanne
12 AND I.matriculeTech = '$matricule'
13 ORDER BY I.dateIntervention DESC";
14
15 // Tâche ❸ : Exécution de la requête
16 $res = mysqli_query($con, $req);
17
18 // Tâche ❹ : Vérifier s'il y a des résultats
19 if (mysqli_num_rows($res) > 0) {
20 echo "<table border='1'>";
21 echo "<tr><th>Code</th><th>Date</th><th>Ordinateur</th><th>Panne</th><th>Statut</th></tr>";
22
23 // Tâche ❺ : Parcourir les résultats
24 while ($enreg = mysqli_fetch_array($res)) {
25 echo "<tr>";
26 echo "<td>" . $enreg[0] . "</td>";
27 echo "<td>" . $enreg[1] . "</td>";
28 echo "<td>" . $enreg[2] . "</td>";
29 echo "<td>" . $enreg[3] . "</td>";
30 echo "<td>" . $enreg[4] . "</td>";
31 echo "</tr>";
32 }
33 echo "</table>";
34 } else {
35 echo "Aucune intervention trouvée pour ce technicien.";
36 }
37
38 // Tâche ❻ : Fermeture de la connexion
39 mysqli_close($con);
40 ?>
